from pathlib import Path
from openpyxl import load_workbook
from openpyxl.utils import get_column_letter
path = Path('/root/output/result.xlsx')
print('File exists:', path.exists())
print('File size:', path.stat().st_size if path.exists() else None)
wb = load_workbook(path, keep_vba=False, data_only=False)
print('Sheets:', wb.sheetnames)
ws = wb['Task']

# Verify formulas in every required target cell.
errors = []
for r in list(range(12,18)) + list(range(19,25)) + list(range(26,32)):
    for c in range(8,13):
        col = get_column_letter(c)
        expected = f'=INDEX(Data!$H$21:$L$38,MATCH($D{r},Data!$D$21:$D$38,0),MATCH({col}$10,Data!$H$4:$L$4,0))'
        if ws.cell(r,c).value != expected:
            errors.append((f'{col}{r}', ws.cell(r,c).value, expected))
for out_r, fin_r, scrap_r, cap_r in zip(range(35,41), range(12,18), range(19,25), range(26,32)):
    for c in range(8,13):
        col = get_column_letter(c)
        expected = f'=({col}{fin_r}-{col}{scrap_r})/{col}{cap_r}*100'
        if ws.cell(out_r,c).value != expected:
            errors.append((f'{col}{out_r}', ws.cell(out_r,c).value, expected))
stat_funcs = {42:'MIN',43:'MAX',44:'MEDIAN',45:'AVERAGE'}
for c in range(8,13):
    col = get_column_letter(c)
    for r, fn in stat_funcs.items():
        expected = f'={fn}({col}35:{col}40)'
        if ws.cell(r,c).value != expected:
            errors.append((f'{col}{r}', ws.cell(r,c).value, expected))
    expected = f'=PERCENTILE({col}35:{col}40,0.25)'
    if ws.cell(46,c).value != expected:
        errors.append((f'{col}46', ws.cell(46,c).value, expected))
    expected = f'=PERCENTILE({col}35:{col}40,0.75)'
    if ws.cell(47,c).value != expected:
        errors.append((f'{col}47', ws.cell(47,c).value, expected))
    expected = f'=SUMPRODUCT({col}35:{col}40,{col}26:{col}31)/SUM({col}26:{col}31)'
    if ws.cell(50,c).value != expected:
        errors.append((f'{col}50', ws.cell(50,c).value, expected))

print('Verification errors:', len(errors))
if errors:
    for e in errors[:20]:
        print(e)
    raise SystemExit(1)
print('\nSample formulas after re-open:')
for addr in ['H12','I12','L17','H19','L24','H26','L31','H35','L40','H42','H43','H44','H45','H46','H47','H50','L50']:
    print(f'{addr}: {ws[addr].value}')
print('\nAll required formulas verified after re-opening workbook.')
